var u = $input.first().json;
var m = u.message, cb = u.callback_query;
var o = { kind: 'none' };
if (cb) {
  var cm = cb.message || {};
  o = { kind: 'callback', chat_id: cm.chat ? cm.chat.id : null, chat_type: cm.chat ? cm.chat.type : '', user_id: cb.from ? cb.from.id : null, data: String(cb.data || ''), query_id: cb.id };
} else if (m) {
  o = { kind: 'message', chat_id: m.chat ? m.chat.id : null, chat_type: m.chat ? m.chat.type : '', user_id: m.from ? m.from.id : null, text: String(m.text || '') };
}
return [{ json: o }];

var NL = String.fromCharCode(10);
var p = $('Parse Update').first().json;
var allowed = $input.all().map(function (i) { return i.json.telegram_user_id; }).filter(function (x) { return x; }).map(String);
function out(o) { return [{ json: o }]; }
if (p.kind === 'none' || !p.chat_id || !p.user_id) return out({ action: 'ignore' });
var uid = String(p.user_id);
if (allowed.indexOf(uid) < 0) {
  if (p.chat_type !== 'private') return out({ action: 'ignore' });
  if (p.kind === 'callback') return out({ action: 'static', messages: [{ type: 'ack', queryId: p.query_id, text: 'Not authorized' }] });
  return out({ action: 'static', messages: [{ type: 'text', chatId: p.chat_id, text: '⛔ Not authorized. This is a private bot.' + NL + 'Your Telegram user ID: <code>' + uid + '</code>' + NL + 'The owner must add this ID to the nis_allowed_users data table in n8n.' }] });
}
var base = { chat_id: p.chat_id, user_id: Number(uid) };
function db(cmd, sql) { return out({ action: 'db', cmd: cmd, sql: sql, chat_id: base.chat_id, user_id: base.user_id, query_id: p.query_id || null }); }
function st(text) { return out({ action: 'static', messages: [{ type: 'text', chatId: base.chat_id, text: text }] }); }
var HELP = '<b>AI Networking Intelligence</b>' + NL + 'I research and suggest. You do every LinkedIn action manually. Buttons only record what YOU confirm.' + NL + NL + '/run - start research' + NL + '/people - pending people' + NL + '/posts - pending posts' + NL + '/career - career opportunities' + NL + '/clients - potential clients' + NL + '/status - system status' + NL + '/history - confirmed activity' + NL + '/report - latest report' + NL + '/done - confirm completed activities' + NL + '/stop - stop a running research' + NL + '/help - this list';
if (p.kind === 'callback') {
  var parts = p.data.split(':');
  var uuid = parts[2] || '';
  var ok = uuid.length === 36 && uuid.split('').every(function (ch) { return '0123456789abcdef-'.indexOf(ch) >= 0; });
  var pm = { r: 'reviewed', reviewed: 'reviewed', s: 'sent', sent: 'sent', c: 'connected', connected: 'connected', i: 'ignore', ignore: 'ignore', f: 'followup', followup: 'followup' };
  var om = { r: 'reviewed', reviewed: 'reviewed', c: 'commented', commented: 'commented', s: 'skip', skip: 'skip' };
  var kind = parts[0] === 'p' ? 'person' : (parts[0] === 'o' ? 'post' : null);
  var act = kind === 'person' ? pm[parts[1]] : (kind === 'post' ? om[parts[1]] : null);
  if (!ok || !kind || !act) return out({ action: 'static', messages: [{ type: 'ack', queryId: p.query_id, text: 'Unknown button' }] });
  return db('callback', "select public.nis_apply_user_action('" + kind + "','" + uuid + "'::uuid,'" + act + "'," + base.user_id + ") as r").map(function (x) { x.json.act = act; return x; });
}
var t = p.text.trim();
if (t.charAt(0) !== '/') return st('Send a command. /help shows the list.');
var sp = t.indexOf(' ');
var cmd = (sp < 0 ? t : t.slice(0, sp)).slice(1).split('@')[0].toLowerCase();
if (cmd === 'start' || cmd === 'help') return st(HELP);
if (cmd === 'run') return out({ action: 'run', chat_id: base.chat_id, user_id: base.user_id });
if (cmd === 'people') return db('people', "select public.nis_list_pending_people(8,null) as r");
if (cmd === 'posts') return db('posts', "select public.nis_list_pending_posts(8) as r");
if (cmd === 'career') return db('career', "select jsonb_build_object('jobs',public.nis_list_career(10),'people',public.nis_list_pending_people(6,'career_opportunity')) as r");
if (cmd === 'clients') return db('clients', "select public.nis_list_pending_people(8,'potential_client') as r");
if (cmd === 'status') return db('status', "select public.nis_status() as r");
if (cmd === 'history') return db('history', "select public.nis_history(15) as r");
if (cmd === 'report') return db('report', "select public.nis_latest_report() as r");
if (cmd === 'done') return db('done', "select jsonb_build_object('people',public.nis_list_pending_people(5,null),'posts',public.nis_list_pending_posts(5)) as r");
if (cmd === 'stop') return db('stop', "select public.nis_request_stop() as r");
return st('Unknown command. /help shows the list.');

var NL = String.fromCharCode(10);
var ctx = $('Authorize and Route').first().json;
if (ctx.action === 'static') return ctx.messages.map(function (m) { return { json: m }; });
var first = $input.first().json;
var c = ctx.chat_id;
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function cut(s) { return s.length > 3900 ? s.slice(0, 3890) + '...' : s; }
function tier(s) { return s >= 85 ? 'Highly Valuable' : (s >= 70 ? 'Strong Match' : (s >= 55 ? 'Moderate' : 'Not Recommended')); }
function txt(t) { return { json: { type: 'text', chatId: c, text: cut(t) } }; }
if (first.r === undefined || first.error) return [txt('⚠️ Database request failed. Try again in a moment. If it keeps failing use /status.')];
var r = first.r; var out = [];
function person(x) {
  var t = ['👤 <b>' + esc(x.name) + '</b>', esc(x.position) + (x.company ? ' @ ' + esc(x.company) : ''), 'Score <b>' + x.score + '</b> (' + tier(x.score) + ') · ' + esc(x.category) + ' · confidence ' + esc(x.confidence) + ' · status ' + esc(x.status), 'Why: ' + esc(x.reason || 'n/a'), 'Evidence: ' + esc(x.evidence_url || x.profile_url), '', '✉️ Suggested message (tap to copy):', '<code>' + esc(x.connection_message || '') + '</code>'].join(NL);
  return { json: { type: 'person', chatId: c, id: x.id, url: x.profile_url, text: cut(t) } };
}
function post(x) {
  var t = ['📝 <b>' + esc(x.author_name || 'Unknown author') + '</b>' + (x.company ? ' · ' + esc(x.company) : ''), 'Topic: ' + esc(x.topic), 'Relevance ' + x.relevance_score + ' · ' + esc(x.networking_value || ''), (x.content_basis !== 'full' ? '⚠️ Based on a search snippet only. Read the full post before commenting.' : ''), '', '💬 Suggested comment (tap to copy):', '<code>' + esc(x.suggested_comment || '') + '</code>', (x.alternative_comment ? 'Alternative:' + NL + '<code>' + esc(x.alternative_comment) + '</code>' : ''), 'Source: ' + esc(x.post_url)].join(NL);
  return { json: { type: 'post', chatId: c, id: x.id, url: x.post_url, text: cut(t) } };
}
var cmd = ctx.cmd;
if (cmd === 'people' || cmd === 'clients') {
  if (!r.length) return [txt(cmd === 'people' ? 'No pending people recommendations. Send /run to research.' : 'No pending potential-client recommendations.')];
  return r.map(person);
}
if (cmd === 'posts') {
  if (!r.length) return [txt('No pending post recommendations. Send /run to research.')];
  return r.map(post);
}
if (cmd === 'career') {
  var jobs = r.jobs || []; var ver = jobs.filter(function (j) { return j.bangladesh_eligibility === 'verified_accepts' || j.is_bangladesh_based; });
  var unv = jobs.filter(function (j) { return !(j.bangladesh_eligibility === 'verified_accepts' || j.is_bangladesh_based); });
  var lines = ['💼 <b>Career opportunities</b>', 'Verified (accepts Bangladesh or Bangladesh-based):'];
  if (!ver.length) lines.push('none');
  ver.forEach(function (j) { lines.push('• ' + esc(j.title) + ' @ ' + esc(j.company) + ' — ' + esc(j.eligibility_evidence || 'Bangladesh-based') + ' ' + esc(j.job_url)); });
  lines.push(NL + 'Eligibility UNVERIFIED (check before applying):');
  if (!unv.length) lines.push('none');
  unv.forEach(function (j) { lines.push('• ' + esc(j.title) + ' @ ' + esc(j.company) + ' (' + esc(j.remote_policy) + ') ' + esc(j.job_url)); });
  out.push(txt(lines.join(NL)));
  (r.people || []).forEach(function (x) { out.push(person(x)); });
  return out;
}
if (cmd === 'done') {
  out.push(txt('✅ <b>Confirm completed activities</b>' + NL + 'Tap a button ONLY for things you already did manually on LinkedIn. Nothing is assumed.'));
  (r.people || []).forEach(function (x) { out.push(person(x)); });
  (r.posts || []).forEach(function (x) { out.push(post(x)); });
  if (!(r.people || []).length && !(r.posts || []).length) out.push(txt('Nothing pending.'));
  return out;
}
if (cmd === 'status') {
  var lr = r.latest_run || {};
  return [txt(['📡 <b>Status</b>', 'Running now: ' + (r.is_running ? 'yes' : 'no'), 'Last run: ' + esc(lr.execution_id || 'none') + ' (' + esc(lr.status || '-') + ') ' + esc(lr.started_at || ''), 'People tracked: ' + r.people_total + ' · pending: ' + r.people_pending, 'Posts pending: ' + r.posts_pending, 'Confirmed activities: ' + r.activities_total, 'Errors (24h): ' + r.recent_errors_24h].join(NL))];
}
if (cmd === 'history') {
  if (!r.length) return [txt('No confirmed activity yet. Activity is recorded only when you press a Mark button.')];
  return [txt('🕘 <b>History</b>' + NL + r.map(function (h) { return esc(String(h.occurred_at).slice(0, 10)) + ' · ' + esc(h.activity_type) + ' · ' + esc(h.person_name || h.post_author || '') + (h.company ? ' (' + esc(h.company) + ')' : ''); }).join(NL))];
}
if (cmd === 'report') {
  if (!r.report_text) return [txt('No report yet. Send /run.')];
  return [txt(r.report_text)];
}
if (cmd === 'stop') {
  return [txt(r.running_runs_flagged > 0 ? '🛑 Stop requested. The run will stop at its next safe checkpoint.' : 'No research is running.')];
}
if (cmd === 'callback') {
  var labels = { reviewed: 'Marked reviewed', sent: 'Marked: connection request sent', connected: 'Marked connected', ignore: 'Skipped', followup: 'Follow-up needed', commented: 'Marked commented', skip: 'Skipped' };
  var msg = r.ok ? ('✅ ' + (labels[ctx.act] || 'Saved')) : ('⚠️ Not changed: ' + (r.error === 'invalid_transition' ? 'already ' + r.current : r.error));
  return [{ json: { type: 'ack', queryId: ctx.query_id, text: msg } }];
}
return [txt('Done.')];
